## Section 2: Wire Format, Bytecode & API Schemas

To ensure interoperability across heterogeneous agent fabrics and scheduling planes, DDGP-EMOP mandates a binary-packed Protocol Buffers (v3) wire format for control-plane communication, and a highly optimized JSON schema for event ingestion.

### 2.1 Control Plane Wire Format (Protobuf Specification)

```protobuf
syntax = "proto3";

package ddgp.emop.v1;

import "google/protobuf/timestamp.proto";

enum VMStatus {
  VM_STATUS_UNSPECIFIED = 0;
  VM_STATUS_PROVISIONING = 1;
  VM_STATUS_RUNNING = 2;
  VM_STATUS_COMPLETED = 3;
  VM_STATUS_FAILED = 4;
  VM_STATUS_TIMEOUT = 5;
}

message CommitMetadata {
  string commit_sha = 1;
  string branch = 2;
  google.protobuf.Timestamp timestamp = 3;
  repeated string modified_files = 4;
}

message DependencyNode {
  string target_id = 1;
  repeated string dependencies = 2;
  repeated string test_sources = 3;
  string hash = 4;
}

message ExecutionRequest {
  string request_id = 1;
  CommitMetadata metadata = 2;
  repeated string target_tests = 3;
  uint32 max_memory_mb = 4;
  uint32 vcpu_count = 5;
  uint32 timeout_ms = 6;
}

message ExecutionResponse {
  string request_id = 1;
  string vm_id = 2;
  VMStatus status = 3;
  int32 exit_code = 4;
  bytes stdout = 5;
  bytes stderr = 6;
  uint64 execution_duration_us = 7;
  uint64 memory_peak_bytes = 8;
}
```

### 2.2 MicroVM Configuration Schema (JSON)
When the EMOP orchestrator provisions a new Firecracker microVM, it serializes the following schema and sends it over the local Unix Domain Socket (UDS) interface of the Firecracker API server [3]:

```json
{
  "boot-source": {
    "kernel_image_path": "/var/lib/emop/kernels/vmlinux-6.1.bin",
    "boot_args": "console=ttyS0 reboot=k panic=1 pci=off nomodules quiet root=/dev/vda rw"
  },
  "drives": [
    {
      "drive_id": "rootfs",
      "path_on_host": "/var/lib/emop/snapshots/rootfs-base.ext4",
      "is_root_device": true,
      "is_read_only": true
    },
    {
      "drive_id": "scratchpad",
      "path_on_host": "/var/lib/emop/runs/run_90812_overlay.ext4",
      "is_root_device": false,
      "is_read_only": false
    }
  ],
  "machine-config": {
    "vcpu_count": 2,
    "mem_size_mib": 512,
    "smt": false,
    "track_dirty_pages": false
  },
  "network-interfaces": [
    {
      "iface_id": "eth0",
      "host_dev_name": "tap_90812"
    }
  ]
}
```

