## Section 3: Reference Implementation with Annotated Code Blocks

Below is the reference implementation of the DDGP core graph-pruning engine and the EMOP microVM execution controller, implemented in production-grade Rust. It utilizes an asynchronous, lock-free design pattern to maximize throughput and minimize lock contention.

### 3.1 Lock-Free Incremental Dependency Graph Pruner

```rust
use std::collections::{HashMap, HashSet};
use std::sync::Arc;
use tokio::sync::RwLock;
use std::sync::atomic::{AtomicU32, Ordering};

#[derive(Debug, Clone)]
pub struct TargetNode {
    pub id: String,
    pub dependencies: Vec<String>,
    pub test_files: Vec<String>,
    pub state_version: Arc<AtomicU32>,
}

pub struct DependencyGraph {
    // Map of target ID to its corresponding TargetNode
    pub nodes: Arc<HashMap<String, TargetNode>>,
    // Reverse lookup map: Target ID to targets that depend on it
    pub dependents: Arc<HashMap<String, Vec<String>>>,
}

impl DependencyGraph {
    pub fn new(nodes: HashMap<String, TargetNode>) -> Self {
        let mut dependents: HashMap<String, Vec<String>> = HashMap::new();
        for (node_id, node) in &nodes {
            for dep in &node.dependencies {
                dependents
                    .entry(dep.clone())
                    .or_default()
                    .push(node_id.clone());
            }
        }

        Self {
            nodes: Arc::new(nodes),
            dependents: Arc::new(dependents),
        }
    }

    /// Performs deterministic pruning to identify affected test targets
    /// given a set of modified files.
    pub async fn prune_dependencies(&self, modified_files: &[String]) -> HashSet<String> {
        let mut affected_targets = HashSet::new();
        let mut queue = Vec::new();

        // Step 1: Map modified files back to their immediate compilation targets
        for (target_id, node) in self.nodes.iter() {
            for file in modified_files {
                if node.test_files.contains(file) || node.id == *file {
                    queue.push(target_id.clone());
                    affected_targets.insert(target_id.clone());
                }
            }
        }

        // Step 2: Traverse the reverse dependency graph to find all affected dependents
        let mut visited = HashSet::new();
        while let Some(current_target) = queue.pop() {
            if !visited.insert(current_target.clone()) {
                continue;
            }

            if let Some(deps) = self.dependents.get(&current_target) {
                for dep_target in deps {
                    if affected_targets.insert(dep_target.clone()) {
                        queue.push(dep_target.clone());
                    }
                }
            }
        }

        affected_targets
    }
}
```

### 3.2 Ephemeral MicroVM Controller (Firecracker Integration)

```rust
use std::path::PathBuf;
use std::process::Stdio;
use tokio::process::Command;
use tokio::net::UnixStream;
use tokio::io::{AsyncWriteExt, AsyncReadExt};
use std::time::Duration;

pub struct MicroVMConfig {
    pub vm_id: String,
    pub socket_path: PathBuf,
    pub rootfs_path: PathBuf,
    pub overlay_path: PathBuf,
    pub tap_device: String,
    pub vcpu_count: u32,
    pub mem_size_mb: u32,
}

pub struct EphemeralMicroVM {
    config: MicroVMConfig,
}

impl EphemeralMicroVM {
    pub fn new(config: MicroVMConfig) -> Self {
        Self { config }
    } 

    /// Spawns the Firecracker VMM process and configures it via Unix Domain Socket
    pub async fn spawn_and_run(&self, run_payload: &str) -> Result<String, Box<dyn std::error::Error>> {
        // Step 1: Start Firecracker process
        let mut child = Command::new("/usr/bin/firecracker")
            .arg("--api-sock")
            .arg(&self.config.socket_path)
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()?;

        // Wait briefly for the socket to initialize
        tokio::time::sleep(Duration::from_millis(5)).await;

        // Step 2: Connect to API Socket and configure VM
        let mut stream = UnixStream::connect(&self.config.socket_path).await?;

        // Send boot source configuration
        let boot_config = serde_json::json!({
            "boot-source": {
                "kernel_image_path": "/var/lib/emop/kernels/vmlinux-6.1.bin",
                "boot_args": "console=ttyS0 reboot=k panic=1 pci=off nomodules quiet root=/dev/vda rw"
            }
        });
        self.send_api_request(&mut stream, "PUT", "/boot-source", &boot_config.to_string()).await?;

        // Send drive configuration with the read-only rootfs and writable overlay
        let drive_config = serde_json::json!({
            "drive_id": "rootfs",
            "path_on_host": self.config.rootfs_path.to_str().unwrap(),
            "is_root_device": true,
            "is_read_only": true
        });
        self.send_api_request(&mut stream, "PUT", "/drives/rootfs", &drive_config.to_string()).await?;

        // Configure machine specs
        let machine_config = serde_json::json!({
            "vcpu_count": self.config.vcpu_count,
            "mem_size_mib": self.config.mem_size_mb
        });
        self.send_api_request(&mut stream, "PUT", "/machine-config", &machine_config.to_string()).await?;

        // Start the VM instance
        let action_config = serde_json::json!({
            "action_type": "InstanceStart"
        });
        self.send_api_request(&mut stream, "PUT", "/actions", &action_config.to_string()).await?;

        // Step 3: Monitor execution and capture outputs (Mock implementation of output retrieval)
        let status = child.wait().await?;
        if !status.success() {
            return Err("Firecracker process exited with error".into());
        }

        Ok(format!("VM {} completed successfully", self.config.vm_id))
    }

    async fn send_api_request(
        &self, 
        stream: &mut UnixStream, 
        method: &str, 
        path: &str, 
        body: &str
    ) -> Result<(), Box<dyn std::error::Error>> {
        let request = format!(
            "{} {} HTTP/1.1\\r\
Host: localhost\\r\
Content-Type: application/json\\r\
Content-Length: {}\\r\
Connection: close\\r\
\\r\
{}
```

",
            method, path, body.len(), body
        );

        use tokio::io::{AsyncReadExt, AsyncWriteExt};
        stream.write_all(request.as_bytes()).await?;

        let mut response_buf = [0u8; 4096];
        let bytes_read = stream.read(&mut response_buf).await?;
        let response_str = String::from_utf8_lossy(&response_buf[..bytes_read]);

        // Evaluate HTTP status codes from the Firecracker management socket
        if !response_str.starts_with("HTTP/1.1 200") && !response_str.starts_with("HTTP/1.1 204") {
            return Err(format!(
                "Firecracker API error on [{} {}]: {}",
                method, path, response_str
            )
            .into());
        }

        Ok(())
    }
}
```


