## 3. Reference Implementation with Annotated Code Blocks

The following Rust implementation demonstrates the core mechanics of registering a memory region with `userfaultfd`, spawning a background page-fault handling thread, capturing original pages, and performing a zero-latency rollback upon transaction abortion.

```rust
use libc::{
    ioctl, mmap, munmap, syscall, MAP_ANONYMOUS, MAP_PRIVATE, PROT_READ, PROT_WRITE, SYS_userfaultfd,
};
use std::collections::HashMap;
use std::fs::File;
use std::io::{Read, Write};
use std::os::unix::io::AsRawFd;
use std::sync::{Arc, Mutex};
use std::thread;

const UFFDIO_API: u64 = 0xAA01;
const UFFDIO_REGISTER: u64 = 0xAA02;
const UFFDIO_COPY: u64 = 0xAA03;

#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct UffdioApi {
    pub api: u64,
    pub features: u64,
    pub ioctls: u64,
}

#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct UffdioRange {
    pub start: u64,
    pub len: u64,
}

#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct UffdioRegister {
    pub range: UffdioRange,
    pub mode: u64,
    pub ioctls: u64,
}

#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct UffdioCopy {
    pub dst: u64,
    pub src: u64,
    pub len: u64,
    pub mode: u64,
    pub copy: i64,
}

/// Represents the active rollback ledger containing unmodified backup pages.
pub struct RollbackLedger {
    pub original_pages: HashMap<usize, Vec<u8>>,
    pub page_size: usize,
}

pub struct TsepEngine {
    base_address: *mut libc::c_void,
    region_size: usize,
    uffd: i32,
    ledger: Arc<Mutex<RollbackLedger>>,
    handler_thread: Option<thread::JoinHandle<()>>,
}

impl TsepEngine {
    pub fn new(region_size: usize) -> Result<Self, String> {
        let page_size = unsafe { libc::sysconf(libc::_SC_PAGESIZE) as usize };
        if region_size % page_size != 0 {
            return Err("Region size must be aligned to system page size.".to_string());
        }

        // 1. Allocate anonymous memory mapping
        let base_address = unsafe {
            mmap(
                std::ptr::null_mut(),
                region_size,
                PROT_READ | PROT_WRITE,
                MAP_PRIVATE | MAP_ANONYMOUS,
                -1,
                0,
            )
        };
        if base_address == libc::MAP_FAILED {
            return Err("Failed to allocate virtual memory region via mmap.".to_string());
        }

        // 2. Initialize userfaultfd system call
        let uffd = unsafe { syscall(SYS_userfaultfd, 0) as i32 };
        if uffd < 0 {
            return Err("Failed to initialize userfaultfd. Ensure CAP_SYS_PTRACE is enabled.".to_string());
        }

        // 3. Enable UFFD API
        let mut uffdio_api = UffdioApi {
            api: 0xAA, // UFFD_API version
            features: 0,
            ioctls: 0,
        };
        unsafe {
            if ioctl(uffd, UFFDIO_API as _, &mut uffdio_api) < 0 {
                return Err("ioctl UFFDIO_API negotiation failed.".to_string());
            }
        }

        // 4. Register memory range for write-fault monitoring
        let mut uffdio_register = UffdioRegister {
            range: UffdioRange {
                start: base_address as u64,
                len: region_size as u64,
            },
            mode: 1, // UFFDIO_REGISTER_MODE_MISSING
            ioctls: 0,
        };
        unsafe {
            if ioctl(uffd, UFFDIO_REGISTER as _, &mut uffdio_register) < 0 {
                return Err("ioctl UFFDIO_REGISTER failed to bind memory range.".to_string());
            }
        }

        let ledger = Arc::new(Mutex::new(RollbackLedger {
            original_pages: HashMap::new(),
            page_size,
        }));

        Ok(TsepEngine {
            base_address,
            region_size,
            uffd,
            ledger,
            handler_thread: None,
        })
    }

    /// Spawns the user-space page fault handler loop
    pub fn start_fault_handler(&mut self) {
        let uffd = self.uffd;
        let ledger_clone = Arc::clone(&self.ledger);
        let base_addr = self.base_address as usize;
        let size = self.region_size;

        let handle = thread::spawn(move || {
            let mut uffd_file = unsafe { std::fs::File::from_raw_fd(uffd) };
            let mut buf = [0u8; 32]; // Buffer to read uffd_msg

            loop {
                match uffd_file.read_exact(&mut buf) {
                    Ok(_) => {
                        // Extract fault address from the kernel message structure
                        let fault_address = usize::from_ne_bytes(buf[16..24].try_into().unwrap());
                        let page_start = fault_address & !(4096 - 1);

                        let mut ledger = ledger_clone.lock().unwrap();
                        if !ledger.original_pages.contains_key(&page_start) {
                            // Capture the pre-mutation state (shadowing)
                            let mut original_data = vec![0u8; ledger.page_size];
                            unsafe {
                                std::ptr::copy_nonoverlapping(
                                    page_start as *const u8,
                                    original_data.as_mut_ptr(),
