## 3. Byte-Level Guardrail Engine (BGE) Reference Implementation

The Byte-Level Guardrail Engine (BGE) is the core execution unit responsible for parsing, validating, and enforcing the DBGP frame invariants. To meet the sub-millisecond latency requirements of high-throughput autonomous agent tool execution, the reference implementation is written in standard, dependency-free Rust. It utilizes zero-copy parsing techniques to prevent memory allocation overhead on the hot path.

Below is the complete, production-grade implementation of the DBGP frame parser, validation pipeline, and Shannon entropy calculation engine.

```rust
//! DBGP Frame Parser and Validation Engine
//! Reference Implementation - RFC-0491
//! Author: Lorapok Labs Systems Architecture Group

use std::collections::HashMap;
use std::convert::TryInto;

/// DBGP Protocol Constants
pub const DBGP_MAGIC: u16 = 0xDBGP;
pub const DBGP_HEADER_SIZE: usize = 28;

/// DBGP Control Flags
pub const FLAG_TEXT_PAYLOAD: u8 = 0x01;
pub const FLAG_BINARY_PAYLOAD: u8 = 0x02;
pub const FLAG_END_OF_STREAM: u8 = 0x04;

#[derive(Debug, PartialEq, Eq)]
pub enum DBGPValidationError {
    IncompleteHeader,
    InvalidMagic,
    UnsupportedVersion,
    PayloadLengthMismatch,
    EntropyExceeded,
    InvalidUTF8,
    SequenceDrift,
    InvalidFlags,
}

/// Decoded DBGP Frame Header representing the 28-byte wire format.
#[derive(Debug, Clone)]
pub struct DBGPHeader {
    pub magic: u16,
    pub version: u8,
    pub flags: u8,
    pub payload_length: u32,
    pub entropy_limit: f32,
    pub sequence_number: u64,
    pub reserved: u64,
}

/// Stateful tracking struct maintained within the secure enclave boundary.
pub struct DBGPState {
    pub expected_sequence_number: u64,
    pub global_entropy_default: f32,
}

impl DBGPState {
    pub fn new(initial_seq: u64, default_entropy: f32) -> Self {
        Self {
            expected_sequence_number: initial_seq,
            global_entropy_default: default_entropy,
        }
    }
}

/// Parses the raw 28-byte header from the front of the incoming stream.
pub fn parse_header(buffer: &[u8]) -> Result<DBGPHeader, DBGPValidationError> {
    if buffer.len() < DBGP_HEADER_SIZE {
        return Err(DBGPValidationError::IncompleteHeader);
    }

    let magic = u16::from_be_bytes(buffer[0..2].try_into().unwrap());
    let version = buffer[2];
    let flags = buffer[3];
    let payload_length = u32::from_be_bytes(buffer[4..8].try_into().unwrap());
    let entropy_limit = f32::from_be_bytes(buffer[8..12].try_into().unwrap());
    let sequence_number = u64::from_be_bytes(buffer[12..20].try_into().unwrap());
    let reserved = u64::from_be_bytes(buffer[20..28].try_into().unwrap());

    if magic != DBGP_MAGIC {
        return Err(DBGPValidationError::InvalidMagic);
    }

    if version != 0x01 {
        return Err(DBGPValidationError::UnsupportedVersion);
    }

    Ok(DBGPHeader {
        magic,
        version,
        flags,
        payload_length,
        entropy_limit,
        sequence_number,
        reserved,
    })
}

/// Calculates the Shannon Entropy of a given byte slice.
/// Formula: H(X) = -sum( P(x_i) * log2(P(x_i)) )
pub fn calculate_shannon_entropy(payload: &[u8]) -> f32 {
    if payload.is_empty() {
        return 0.0;
    }

    let mut byte_frequencies = [0usize; 256];
    for &byte in payload {
        byte_frequencies[byte as usize] += 1;
    }

    let len = payload.len() as f64;
    let mut entropy = 0.0f64;

    for &count in byte_frequencies.iter() {
        if count > 0 {
            let probability = count as f64 / len;
            entropy -= probability * probability.log2();
        }
    }

    entropy as f32
}

/// Validates the frame payload against the parsed header and stateful policies.
pub fn validate_frame(
    header: &DBGPHeader,
    payload: &[u8],
    state: &mut DBGPState,
) -> Result<(), DBGPValidationError> {
    // 1. Verify exact payload length matching
    if payload.len() != header.payload_length as usize {
        return Err(DBGPValidationError::PayloadLengthMismatch);
    }

    // 2. Strict sequence number validation to prevent replay/injection
    if header.sequence_number != state.expected_sequence_number {
        return Err(DBGPValidationError::SequenceDrift);
    }

    // 3. Flag validation: Must be text OR binary, not both, unless stream is ending empty
    let is_text = (header.flags & FLAG_TEXT_PAYLOAD) != 0;
    let is_binary = (header.flags & FLAG_BINARY_PAYLOAD) != 0;
    if is_text && is_binary {
        return Err(DBGPValidationError::InvalidFlags);
    }

    // 4. UTF-8 Validation for text payloads
    if is_text {
        if std::str::from_utf8(payload).is_err() {
            return Err(DBGPValidationError::InvalidUTF8);
        }
    }

    // 5. Entropy calculation and threshold enforcement
    let effective_entropy_limit = if header.entropy_limit > 0.0 {
        header.entropy_limit
    } else {
        state.global_entropy_default
    };

    let actual_entropy = calculate_shannon_entropy(payload);
    if actual_entropy > effective_entropy_limit {
        return Err(DBGPValidationError::EntropyExceeded);
    }

    // Advance sequence state upon successful validation
    state.expected_sequence_number += 1;

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_text_frame() {
        let mut state = DBGPState::new(100, 4.5);
        let payload = b"Hello, this is a secure, low-entropy text stream sent by an agent.";
        let entropy_limit: f32 = 4.0;

        let mut header_bytes = Vec::new();
        header_bytes.extend_from_slice(&DBGP_MAGIC.to_be_bytes());
        header_bytes.push(0x01); // Version
        header_bytes.push(FLAG_TEXT_PAYLOAD); // Flags
        header_bytes.extend_from_slice(&(payload.len() as u32).to_be_bytes());
        header_bytes.extend_from_slice(&entropy_limit.to_be_bytes());
        header_bytes.extend_from_slice(&100u64.to_be_bytes()); // Seq
        header_bytes.extend_from_slice(&0u64.to_be_bytes()); // Reserved

        let header = parse_header(&header_bytes).unwrap();
        let result = validate_frame(&header, payload, &mut state);

        assert!(result.is_ok());
        assert_eq!(state.expected_sequence_number, 101);
    }

    #[test]
    fn test_high_entropy_rejection() {
        let mut state = DBGPState::new(200, 3.0);
        // High entropy random-looking payload
        let payload: [u8; 32] = [
            0x1a, 0xf3, 0x8c, 0x92, 0x01, 0xfe, 0xdd, 0xba,
            0x55, 0x44, 0x33, 0x22, 0x11, 0xaa, 0xbb, 0xcc,
            0x99, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22,
            0x12, 0x34, 0x56, 0x78, 0x9a, 0xbc, 0xde, 0xf0
        ];

        let mut header_bytes = Vec::new();
        header_bytes.extend_from_slice(&DBGP_MAGIC.to_be_bytes());
        header_bytes.push(0x01);
        header_bytes.push(FLAG_BINARY_PAYLOAD);
        header_bytes.extend_from_slice(&(payload.len() as u32).to_be_bytes());
        header_bytes.extend_from_slice(&3.5f32.to_be_bytes()); // Limit set below actual entropy
        header_bytes.extend_from_slice(&200u64.to_be_bytes());
        header_bytes.extend_from_slice(&0u64.to_be_bytes());

        let header = parse_header(&header_bytes).unwrap();
        let result = validate_frame(&header, &payload, &mut state);

        assert_eq!(result, Err(DBGPValidationError::EntropyExceeded));
        // Ensure sequence number did not advance on failure
        assert_eq!(state.expected_sequence_number, 200);
    }
}
