## Section 3: Reference Implementation with Annotated Code Blocks

The following production-grade Rust implementation provides the core lock-free Intent Ring Buffer (IRB) coupled with write-ahead memory synchronization logic. It enforces 64-byte L1 cache-line boundary alignment using `#[repr(C, align(64))]` to protect high-frequency producer/consumer queues from cross-core cache invalidation sweeps [3].

```rust
use std::sync::atomic::{AtomicU64, AtomicU8, Ordering};
use std::sync::Arc;
use std::mem::MaybeUninit;

pub const ATEP_MAGIC: u16 = 0x4154; // "AT"
pub const RING_BUFFER_CAPACITY: usize = 1024; // Must be power of 2

/// Packed 128-byte ATEP Frame Header aligned to 64-byte cache bounds.
#[repr(C, align(64))]
#[derive(Debug, Clone, Copy)]
pub struct AFrameHeader {
    pub magic: u16,
    pub version: u8,
    pub opcode: u8,
    pub flags: u32,
    pub sequence_id: u64,
    pub timestamp_ns: u64,
    pub nonce: [u8; 16],
    pub payload_hash: [u8; 32],
    pub payload_len: u32,
    pub timeout_ms: u32,
    pub checksum: u32,
    _padding: [u8; 44],
}

impl Default for AFrameHeader {
    fn default() -> Self {
        Self {
            magic: ATEP_MAGIC,
            version: 0x01,
            opcode: 0x01,
            flags: 0,
            sequence_id: 0,
            timestamp_ns: 0,
            nonce: [0u8; 16],
            payload_hash: [0u8; 32],
            payload_len: 0,
            timeout_ms: 1500,
            checksum: 0,
            _padding: [0u8; 44],
        }
    }
}

/// Cache-Line Aligned Atomic Metadata to isolate Producer and Consumer contention boundaries.
#[repr(C, align(64))]
struct CacheAlignedHead {
    value: AtomicU64,
}

#[repr(C, align(64))]
struct CacheAlignedTail {
    value: AtomicU64,
}

/// Lock-Free SPSC Ring Buffer for ATEP Frame Transfer.
pub struct AtepIntentRingBuffer {
    head: CacheAlignedHead,
    tail: CacheAlignedTail,
    buffer: Box<[MaybeUninit<AFrameHeader>; RING_BUFFER_CAPACITY]>,
    states: Box<[AtomicU8; RING_BUFFER_CAPACITY]>,
}

// Frame Slot States
const SLOT_EMPTY: u8 = 0;
const SLOT_WRITING: u8 = 1;
const SLOT_READY: u8 = 2;
const SLOT_READING: u8 = 3;

impl AtepIntentRingBuffer {
    pub fn new() -> Self {
        // Allocate raw uninitialized array safely
        let buffer = unsafe {
            Box::new(MaybeUninit::uninit().assume_init())
        };

        let mut states_vec = Vec::with_capacity(RING_BUFFER_CAPACITY);
        for _ in 0..RING_BUFFER_CAPACITY {
            states_vec.push(AtomicU8::new(SLOT_EMPTY));
        }

        Self {
            head: CacheAlignedHead { value: AtomicU64::new(0) },
            tail: CacheAlignedTail { value: AtomicU64::new(0) },
            buffer,
            states: states_vec.into_boxed_slice().try_into().unwrap_or_else(|_| panic!("Buffer allocation size mismatch")),
        }
    }

    /// Pushes a new Intent Frame into the ring buffer using Acquire/Release synchronization.
    pub fn try_enqueue(&self, frame: AFrameHeader) -> Result<u64, &'static str> {
        let tail = self.tail.value.load(Ordering::Relaxed);
        let head = self.head.value.load(Ordering::Acquire);

        if tail.wrapping_sub(head) >= RING_BUFFER_CAPACITY as u64 {
            return Err("IRB_BUFFER_FULL");
        }

        let index = (tail as usize) & (RING_BUFFER_CAPACITY - 1);

        // Transition slot state: EMPTY -> WRITING
        if self.states[index].compare_exchange(
            SLOT_EMPTY,
            SLOT_WRITING,
            Ordering::Acquire,
            Ordering::Relaxed,
        ).is_err() {
            return Err("IRB_SLOT_BUSY");
        }

        // Write payload to uninitialized slot via raw pointer mutation
        unsafe {
            let slot_ptr = self.buffer[index].as_ptr() as *mut AFrameHeader;
            std::ptr::write(slot_ptr, frame);
        }

        // Transition slot state: WRITING -> READY
        self.states[index].store(SLOT_READY, Ordering::Release);

        // Advance tail pointer
        self.tail.value.store(tail.wrapping_add(1), Ordering::Release);

        Ok(frame.sequence_id)
    }

    /// Dequeues an Intent Frame for execution processing.
    pub fn try_dequeue(&self) -> Option<AFrameHeader> {
        let head = self.head.value.load(Ordering::Relaxed);
        let tail = self.tail.value.load(Ordering::Acquire);

        if head == tail {
            return None; // Buffer is empty
        }

        let index = (head as usize) & (RING_BUFFER_CAPACITY - 1);

        // Transition slot state: READY -> READING
        if self.states[index].compare_exchange(
            SLOT_READY,
            SLOT_READING,
            Ordering::Acquire,
            Ordering::Relaxed,
        ).is_err() {
            return None;
        }

        // Read payload securely
        let frame = unsafe {
            std::ptr::read(self.buffer[index].as_ptr())
        };

        // Transition slot state: READING -> EMPTY
        self.states[index].store(SLOT_EMPTY, Ordering::Release);

        // Advance head pointer
        self.head.value.store(head.wrapping_add(1), Ordering::Release);

        Some(frame)
    }
}
```

## Durable Write-Ahead Replay Log (WAL) & Crash Recovery Engine

To enforce zero-loss durability guarantees across sudden worker host failures, kernel panics, or power disruptions, the non-blocking Intent Ring-Buffer is tightly integrated with a high-throughput, sequential Write-Ahead Replay Log (WAL). Before any frame transitions to `SLOT_READY` inside the in-memory ring-buffer, its memory representation is appended to an active WAL segment file using vectorized asynchronous I/O (`io_uring`) with `O_DIRECT` flags to bypass host OS page cache non-determinism.

### WAL Frame Layout & Direct Disk Append

```rust
use std::fs::File;
use std::os::unix::fs::OpenOptionsExt;
use std::sync::atomic::{AtomicU64, Ordering};
use std::io::{Error, ErrorKind, Result};

pub const WAL_MAGIC: u32 = 0x41544550; // "ATEP"
pub const SECTOR_SIZE: usize = 4096;

#[repr(C, packed)]
pub struct WalRecordHeader {
    pub magic: u32,
    pub sequence_id: u64,
    pub epoch: u64,
    pub payload_len: u32,
    pub crc32: u32,
}

pub struct WalSegmentWriter {
    file: File,
    write_offset: AtomicU64,
    current_epoch: u64,
}

impl WalSegmentWriter {
    pub fn new(path: &str, epoch: u64) -> Result<Self> {
        let file = std::fs::OpenOptions::new()
            .create(true)
            .read(true)
            .write(true)
            .custom_flags(libc::O_DIRECT | libc::O_DSYNC)
            .open(path)?;

        Ok(Self {
            file,
            write_offset: AtomicU64::new(0),
            current_epoch: epoch,
        })
    }

    /// Appends an intent frame to persistent media prior to ring-buffer state advancement.
    pub fn append_record(&self, sequence_id: u64, payload: &[u8]) -> Result<u64> {
        let total_size = std::mem::size_of::<WalRecordHeader>() + payload.len();
        let aligned_size = (total_size + SECTOR_SIZE - 1) & !(SECTOR_SIZE - 1);

        // Compute CRC32 checksum over raw payload
        let mut hasher = crc32fast::Hasher::new();
        hasher.update(payload);
        let crc32 = hasher.finalize();

        let header = WalRecordHeader {
            magic: WAL_MAGIC,
            sequence_id,
            epoch: self.current_epoch,
            payload_len: payload.len() as u32,
            crc32,
        };

        // Allocate block-aligned write buffer for O_DIRECT write compatibility
        let mut align_buf = vec![0u8; aligned_size];
        unsafe {
            let header_ptr = &header as *const WalRecordHeader as *const u8;
            std::ptr::copy_nonoverlapping(header_ptr, align_buf.as_mut_ptr(), std::mem::size_of::<WalRecordHeader>());
            std::ptr::copy_nonoverlapping(
                payload.as_ptr(),
                align_buf.as_mut_ptr().add(std::mem::size_of::<WalRecordHeader>()),
                payload.len(),
            );
        }

        let offset = self.write_offset.fetch_add(aligned_size as u64, Ordering::SeqCst);

        #[cfg(unix)]
        {
            use std::os::unix::fs::FileExt;
            self.file.write_all_at(&align_buf, offset)?;
        }

        Ok(offset)
    }
}
```

### Crash Recovery & State Reconstruction Algorithm

During node cold boots or dynamic failover takeover, the host process invokes the engine recovery routine. The WAL engine iterates sequentially through the segment files, validating CRC32 signatures and sequence monotonicity. Uncommitted intents detected in the log are re-populated directly into the Non-Blocking Intent Ring-Buffer.

```rust
pub struct RecoveryEngine;

impl RecoveryEngine {
    pub fn replay_segment<F>(segment_path: &str, mut replay_cb: F) -> Result<u64>
    where
        F: FnMut(WalRecordHeader, Vec<u8>) -> Result<()>,
    {
        let mut file = File::open(segment_path)?;
        let file_len = file.metadata()?.len();
        let mut offset: u64 = 0;
        let mut replayed_count = 0;

        let mut header_buf = [0u8; std::mem::size_of::<WalRecordHeader>()];

        while offset + (std::mem::size_of::<WalRecordHeader>() as u64) <= file_len {
            use std::io::Read;
            file.read_exact(&mut header_buf)?;

            let header: WalRecordHeader = unsafe { std::ptr::read(header_buf.as_ptr() as *const _) };
            if header.magic != WAL_MAGIC {
                // Terminate replay on torn write detection or zeroed sector padding
                break;
            }

            let mut payload = vec![0u8; header.payload_len as usize];
            file.read_exact(&mut payload)?;

            // Validate record integrity
            let mut hasher = crc32fast::Hasher::new();
            hasher.update(&payload);
            if hasher.finalize() != header.crc32 {
                return Err(Error::new(ErrorKind::InvalidData, "WAL CRC32 Checksum Mismatch"));
            }

            replay_cb(header, payload)?;
            replayed_count += 1;

            // Advance offset aligned to SECTOR_SIZE
            let total_record_bytes = std::mem::size_of::<WalRecordHeader>() + header.payload_len as usize;
            let aligned_advance = (total_record_bytes + SECTOR_SIZE - 1) & !(SECTOR_SIZE - 1);
            offset += aligned_advance as u64;

            #[cfg(unix)]
            {
                use std::io::Seek;
                file.seek(std::io::SeekFrom::Start(offset))?;
            }
        }

        Ok(replayed_count)
    }
}
```

