#### Code Block 1: Lock-Free, Cache-Aligned SPSC Ring Buffer

This ring buffer coordinates the transfer of state observations from the high-frequency sensor thread to the inference thread without locks or context switches.

```rust
use std::sync::atomic::{AtomicUsize, Ordering};
use std::cell::UnsafeCell;

#[repr(align(64))]
pub struct CacheAlignedSlot<T> {
    pub data: UnsafeCell<T>,
}

pub struct SpscRingBuffer<T, const N: usize> {
    // Padding prevents false sharing between the producer and consumer indices
    _pad1: [u8; 56],
    write_idx: AtomicUsize,
    _pad2: [u8; 56],
    read_idx: AtomicUsize,
    _pad3: [u8; 56],
    ring: [CacheAlignedSlot<T>; N],
}

// Safety: SpscRingBuffer is thread-safe for Single-Producer Single-Consumer configurations.
unsafe impl<T: Send, const N: usize> Sync for SpscRingBuffer<T, N> {}
unsafe impl<T: Send, const N: usize> Send for SpscRingBuffer<T, N> {}

impl<T: Default, const N: usize> SpscRingBuffer<T, N> {
    pub fn new() -> Self {
        // Initialize array with default values safely
        let mut ring: std::mem::MaybeUninit<[CacheAlignedSlot<T>; N]> = std::mem::MaybeUninit::uninit();
        let ring_ptr = ring.as_mut_ptr() as *mut CacheAlignedSlot<T>;
        for i in 0..N {
            unsafe {
                ring_ptr.add(i).write(CacheAlignedSlot {
                    data: UnsafeCell::new(T::default()),
                });
            }
        }
        Self {
            _pad1: [0; 56],
            write_idx: AtomicUsize::new(0),
            _pad2: [0; 56],
            read_idx: AtomicUsize::new(0),
            _pad3: [0; 56],
            ring: unsafe { ring.assume_init() },
        }
    } 

    /// Pushes a new state observation into the ring buffer.
    /// Returns Err if the buffer is full.
    pub fn push(&self, value: T) -> Result<(), T> {
        let write = self.write_idx.load(Ordering::Relaxed);
        let read = self.read_idx.load(Ordering::Acquire);

        if write - read == N {
            return Err(value); // Buffer is full
        }

        let slot = &self.ring[write % N];
        unsafe { *slot.data.get() = value; }

        // Release ordering guarantees that the write to 'data' is visible
        // to the consumer thread once the write index is updated.
        self.write_idx.store(write + 1, Ordering::Release);
        Ok(())
    }

    /// Pops the oldest state observation from the ring buffer.
    /// Returns None if the buffer is empty.
    pub fn pop(&self) -> Option<&T> {
        let read = self.read_idx.load(Ordering::Relaxed);
        let write = self.write_idx.load(Ordering::Acquire);

        if read == write {
            return None; // Buffer is empty
        }

        let slot = &self.ring[read % N];
        // Safety: We have exclusive read access to this slot as the consumer
        let val = unsafe { &*slot.data.get() };

        self.read_idx.store(read + 1, Ordering::Release);
        Some(val)
    }
}
```

#### Code Block 2: Zero-Allocation SIMD-Accelerated Inference Kernel

This kernel demonstrates a single-layer feed-forward pass of our non-autoregressive policy. It uses explicit vectorization (AVX2/NEON compatible via portable SIMD) to calculate actions directly into a pre-allocated target buffer.

```rust
#![feature(portable_simd)]
use std::simd::f32x8;

#[repr(align(64))]
pub struct NonAutoregressiveLayer {
    pub weights: &'static [f32], // Flat layout: [output_dim, input_dim]
    pub bias: &'static [f32],
    pub input_dim: usize,
    pub output_dim: usize,
}

impl NonAutoregressiveLayer {
    /// Executes a forward pass of a linear layer with ReLU activation.
    /// Writes the output directly to the pre-allocated `output` slice.
    /// Zero allocations occur on this execution path.
    #[inline(always)]
    pub fn forward(&self, input: &[f32], output: &mut [f32]) {
        assert_eq!(input.len(), self.input_dim);
        assert_eq!(output.len(), self.output_dim);

        for row in 0..self.output_dim {
            let weight_row_offset = row * self.input_dim;
            let mut sum_vector = f32x8::splat(0.0);
            let mut col = 0;

            // Process 8 elements at a time using SIMD
            while col + 8 <= self.input_dim {
                let w_ptr = self.weights[weight_row_offset + col..].as_ptr();
                let i_ptr = input[col..].as_ptr();

                unsafe {
                    let w_vec = f32x8::from_slice(std::slice::from_raw_parts(w_ptr, 8));
                    let i_vec = f32x8::from_slice(std::slice::from_raw_parts(i_ptr, 8));
                    sum_vector += w_vec * i_vec;
                }
                col += 8;
            }

            // Horizontal sum of the SIMD register
            let mut dot_product = sum_vector.reduce_sum();

            // Process remaining elements (scalar fallback)
            while col < self.input_dim {
                dot_product += self.weights[weight_row_offset + col] * input[col];
                col += 1;
            }

            // Apply bias and ReLU activation inline
            let activated = (dot_product + self.bias[row]).max(0.0);
            output[row] = activated;
        }
    }
}
