## Section 3: Annotated Code Deconstruction

The following production-grade Rust implementations showcase the core infrastructure of the translation runtime.

### Listing 1: Lock-Free Register State Shadow Ring Buffer & Decoding Context

This listing defines the thread-local `VCPUContext` layout, featuring strict alignment, explicit register offsets, and atomic atomic translation lookups.

```rust
use std::sync::atomic::{AtomicU64, AtomicPtr, Ordering};
use std::alloc::{alloc_zeroed, Layout};

/// Represents the 16 standard x86_64 General Purpose Registers (GPRs).
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct GuestGPRs {
    pub rax: u64, pub rbx: u64, pub rcx: u64, pub rdx: u64,
    pub rsi: u64, pub rdi: u64, pub rbp: u64, pub rsp: u64,
    pub r8:  u64, pub r9:  u64, pub r10: u64, pub r11: u64,
    pub r12: u64, pub r13: u64, pub r14: u64, pub r15: u64,
}

/// Thread-local vCPU execution context aligned to 64-byte cache line boundaries.
/// Contains guest state, instruction pointer, and active atomic flags.
#[repr(C, align(64))]
pub struct VCPUContext {
    pub gprs: GuestGPRs,             // 128 bytes (2 x 64-byte Cache Lines)
    pub rip: u64,                    // Guest Instruction Pointer
    pub rflags: u64,                 // Guest Status Flags
    pub fs_base: u64,                // Thread-local storage segment base
    pub gs_base: u64,                // Engine internal segment base
    pub execution_state: AtomicU64,  // Status bitmask (0 = Active, 1 = Interrupted, 2 = Trapped)
    pub _padding: [u8; 16],          // Padding to enforce exact 64-byte multiple
}

/// Atomically resolution table for mapping Guest RIPs to JIT Host Code Addresses.
pub struct TranslationLookupTable {
    buckets: Vec<AtomicU64>,
    capacity_mask: u64,
}

impl TranslationLookupTable {
    pub fn new(capacity_power_of_two: usize) -> Self {
        let capacity = capacity_power_of_two.next_power_of_two();
        let mut buckets = Vec::with_capacity(capacity * 2);
        for _ in 0..(capacity * 2) {
            buckets.push(AtomicU64::new(0));
        }
        Self {
            buckets,
            capacity_mask: (capacity - 1) as u64,
        }
    }

    /// Fast-path lock-free lookup for JIT code location based on Guest RIP.
    #[inline(always)]
    pub fn lookup(&self, guest_rip: u64) -> Option<*const u8> {
        let index = (guest_rip.wrapping_mul(0x9E3779B97F4A7C15) >> 32) & self.capacity_mask;
        let slot_idx = (index * 2) as usize;

        let key = self.buckets[slot_idx].load(Ordering::Acquire);
        if key == guest_rip {
            let host_addr = self.buckets[slot_idx + 1].load(Ordering::Acquire);
            if host_addr != 0 {
                return Some(host_addr as *const u8);
            }
        }
        None
    }

    /// Insert mapping from Guest RIP to Host Code Pointer using CAS semantics.
    pub fn insert(&self, guest_rip: u64, host_code_ptr: *const u8) -> bool {
        let index = (guest_rip.wrapping_mul(0x9E3779B97F4A7C15) >> 32) & self.capacity_mask;
        let slot_idx = (index * 2) as usize;

        // Simple linear probing for collision resolution
        for probe in 0..8 {
            let target_slot = ((slot_idx + probe * 2) % self.buckets.len()) as usize;
            let current_key = self.buckets[target_slot].load(Ordering::Relaxed);

            if current_key == 0 || current_key == guest_rip {
                if self.buckets[target_slot]
                    .compare_exchange(current_key, guest_rip, Ordering::Release, Ordering::Relaxed)
                    .is_ok()
                {
                    self.buckets[target_slot + 1].store(host_code_ptr as u64, Ordering::Release);
                    return true;
                }
            }
        }
        false // Table capacity saturated; triggers table eviction/re-hash
    }
}
