## Section 3: Annotated Code Deconstruction

Below is a complete, production-grade implementation of a unified Rust pipeline. It contains two parts: the device kernel (compiled to `nvptx64-nvidia-cuda`) and the host launcher which manages Unified Memory and executes the kernel via the CUDA Driver API.

### 1. The Device Kernel (`kernel.rs`)

This code is compiled with `#![no_std]` and `#![no_main]`. We use the raw PTX intrinsics to identify the thread and block indices.

```rust
#![no_std]
#![no_main]
#![feature(abi_ptx)]

use core::panic::PanicInfo;

#[panic_handler]
fn panic(_info: &PanicInfo) -> ! {
    loop {}
}

// Ensure the struct matches the host layout exactly
#[repr(C, align(16))]
pub struct MatrixPayload {
    pub width: u32,
    pub height: u32,
    pub alpha: f32,
    pub _padding: u32, // Explicit padding to maintain 16-byte alignment
    pub data_a: *const f32,
    pub data_b: *const f32,
    pub data_out: *mut f32,
}

#[no_mangle] 
pub unsafe extern "ptx-kernel" fn gemm_elementwise(
    payload: *const MatrixPayload,
) {
    // Retrieve thread and block dimensions via PTX assembly
    let block_idx_x = ptx_block_idx_x();
    let block_dim_x = ptx_block_dim_x();
    let thread_idx_x = ptx_thread_idx_x();

    // Calculate global 1D thread index
    let global_idx = (block_idx_x * block_dim_x + thread_idx_x) as usize;

    let p = &*payload;
    let total_elements = (p.width * p.height) as usize;

    if global_idx < total_elements {
        // Perform vector-load operations. LLVM compiles these to ld.global.nc or ld.global.f32
        let val_a = *p.data_a.add(global_idx);
        let val_b = *p.data_b.add(global_idx);

        // Elementwise Multiply-Accumulate
        let result = (val_a * val_b) * p.alpha;

        // Vector-store operation compiled to st.global.f32
        *p.data_out.add(global_idx) = result;
    }
}

// Inline assembly wrappers for PTX special registers
#[inline(always)]
unsafe fn ptx_block_idx_x() -> u32 {
    let mut val: u32;
    core::arch::asm!("mov.u32 {}, %ctaid.x;", out(reg) val);
    val
}

#[inline(always)]
unsafe fn ptx_block_dim_x() -> u32 {
    let mut val: u32;
    core::arch::asm!("mov.u32 {}, %ntid.x;", out(reg) val);
    val
}

#[inline(always)]
unsafe fn ptx_thread_idx_x() -> u32 {
    let mut val: u32;
    core::arch::asm!("mov.u32 {}, %tid.x;", out(reg) val);
    val
}
