    struct thread_time_constraint_policy ttcpolicy;
    ttcpolicy.period      = 125000; // 125 microseconds base period
    ttcpolicy.computation = 90000;  // 90 microseconds execution budget
    ttcpolicy.constraint  = 125000; // 125 microseconds hard deadline
    ttcpolicy.preemptible = 1;

    kern_return_t kr = thread_policy_set(
        pthread_mach_thread_np(pthread_self()),
        THREAD_TIME_CONSTRAINT_POLICY,
        (thread_policy_t)&ttcpolicy,
        THREAD_TIME_CONSTRAINT_POLICY_COUNT
    );

    if (kr != KERN_SUCCESS) {
        // Fall back to Mach priority escalation if real-time scheduling is denied by OS policy
        struct thread_extended_policy extpolicy;
        extpolicy.timeshare = 0; // Disable dynamic priority decay
        thread_policy_set(
            pthread_mach_thread_np(pthread_self()),
            THREAD_EXTENDED_POLICY,
            (thread_policy_t)&extpolicy,
            THREAD_EXTENDED_POLICY_COUNT
        );
    }
