        // Parse Ring-VRF evaluation G1 (Epoch Linkage Tag / Nullifier)
        let vrf_gamma_option = G1Affine::from_compressed(&header.vrf_gamma_g1);
        if vrf_gamma_option.is_none().into() {
            return Err(VerificationError::MalformedG1Point);
        }
