        // Derive deterministic epoch scalar y_i = HashToScalar(capability_id || epoch_seq)
        let y_i = compute_epoch_identity_scalar(header.capability_id, header.epoch_seq);

        // Compute dynamic evaluator point in G2: dynamic_g2 = AccumulatorRoot + (y_i * G2_Generator)
        let dynamic_g2_projective = G2Projective::from(self.accumulator_root_g2)
            + (self.generator_g2 * y_i);
        let dynamic_g2_affine = G2Affine::from(dynamic_g2_projective);

        // Execute optimized multi-Miller loop bilinear pairing equality verification:
        // Equation: e(w_i, AccumulatorRoot + y_i * G2) == e(CapabilityCommitment, G2)
        // Transposed for single final exponentiation: e(w_i, dynamic_g2) * e(CapabilityCommitment, -G2) == 1_Gt
        let neg_generator_g2 = -self.generator_g2;

        let pairing_result = bls12_381::multi_miller_loop(&[
            (&witness_g1, &G2Prepared::from(dynamic_g2_affine)),
            (&cap_commitment_g1, &G2Prepared::from(neg_generator_g2)),
        ]).final_exponentiation();

        if pairing_result != bls12_381::Gt::identity() {
            return Err(VerificationError::BilinearPairingFailed);
        }

        // Extract variable-length Ring-VRF non-interactive zero-knowledge (NIZK) proof slice
        let vrf_proof_bytes = &raw_buffer[HEADER_SIZE..];

