            &vrf_gamma,
            vrf_proof_bytes,
            header.epoch_seq,
            &self.accumulator_root_g2,
        );

        if !vrf_valid {
            return Err(VerificationError::InvalidRingVrfProof);
        }

        Ok(header.epoch_seq)
