## Section 3: Reference Implementation with Annotated Code Blocks

The following production-grade Rust implementation demonstrates the zero-copy binary parser, signature validator, and dataflow taint verifier executing under strict timing constraints.

```rust
use ed25519_dalek::{PublicKey, Signature, Verifier};
use std::convert::TryInto;
use std::fmt;

pub const LATP_MAGIC: [u8; 4] = [0x4C, 0x41, 0x54, 0x50];

#[repr(u64)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CapabilityFlag {
    ReadFs          = 1 << 0,
    WriteFs         = 1 << 1,
    NetEgressHttp   = 1 << 2,
    NetEgressRaw    = 1 << 3,
    ExecSubprocess  = 1 << 4,
    IpcSwarm        = 1 << 5,
}

#[derive(Debug)]
pub enum VerificationError {
    InvalidMagic,
    MalformedHeader,
    SignatureMismatch,
    CapabilityViolation(u64),
    IllegalTaintFlow { param: String, sink: String },
}

impl fmt::Display for VerificationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:?}", self)
    }
}

std::error::Error for VerificationError {}

#[derive(Debug)]
pub struct LatpFrameHeader {
    pub version_major: u8,
    pub version_minor: u8,
    pub flags: u16,
    pub transaction_id: u64,
    pub capability_bitmask: u64,
    pub signature: [u8; 64],
    pub payload_len: u32,
    pub taint_bitmask: u16,
}

pub struct PolicyVerifier {
    agent_public_key: PublicKey,
    allowed_capabilities: u64,
}

impl PolicyVerifier {
    pub fn new(agent_public_key: PublicKey, allowed_capabilities: u64) -> Self {
        Self {
            agent_public_key,
            allowed_capabilities,
        }
    }

    /// Zero-copy header verification and cryptographic attestation
    pub fn verify_frame_header(&self, buffer: &[u8]) -> Result<LatpFrameHeader, VerificationError> {
        if buffer.len() < 80 {
            return Err(VerificationError::MalformedHeader);
        }

        if buffer[0..4] != LATP_MAGIC {
            return Err(VerificationError::InvalidMagic);
        }

        let version_major = buffer[4];
        let version_minor = buffer[5];
        let flags = u16::from_be_bytes(buffer[6..8].try_into().unwrap());
        let transaction_id = u64::from_be_bytes(buffer[8..16].try_into().unwrap());
        let capability_bitmask = u64::from_be_bytes(buffer[16..24].try_into().unwrap());

        let mut signature_bytes = [0u8; 64];
        signature_bytes.copy_from_slice(&buffer[24..88]);

        let payload_len = u32::from_be_bytes(buffer[88..92].try_into().unwrap());
        let taint_bitmask = u16::from_be_bytes(buffer[92..94].try_into().unwrap());

        // 1. Validate capability bitmask limits against authorized capabilities
        if (capability_bitmask & !self.allowed_capabilities) != 0 {
            return Err(VerificationError::CapabilityViolation(capability_bitmask));
        }

        // 2. Cryptographic Attestation over the header fields and payload length
        let sig = Signature::from_bytes(&signature_bytes)
            .map_err(|_| VerificationError::SignatureMismatch)?;

        // Signable message consists of slice up to signature boundary + payload metadata
        let mut signed_data = Vec::with_capacity(24 + payload_len as usize);
        signed_data.extend_from_slice(&buffer[0..24]);
        signed_data.extend_from_slice(&buffer[88..94]);
        if buffer.len() >= 94 + payload_len as usize {
            signed_data.extend_from_slice(&buffer[94..94 + payload_len as usize]);
        } else {
            return Err(VerificationError::MalformedHeader);
        }

        self.agent_public_key
            .verify(&signed_data, &sig)
            .map_err(|_| VerificationError::SignatureMismatch)?;

        Ok(LatpFrameHeader {
            version_major,
            version_minor,
            flags,
            transaction_id,
            capability_bitmask,
            signature: signature_bytes,
            payload_len,
            taint_bitmask,
        })
    }

    /// Evaluates dynamic dataflow taint invariants across payload arguments
    pub fn assert_dataflow_invariants(
        &self,
        header: &LatpFrameHeader,
        tool_name: &str,
        parameters: &std::collections::HashMap<String, String>,
    ) -> Result<(), VerificationError> {
        // Rule 1: High-taint parameters (taint_bitmask > 0) cannot enter ExecSubprocess or WriteFs sinks
        let is_high_risk_sink = tool_name == "execute_shell_command" 
            || tool_name == "write_system_file"
            || (header.capability_bitmask & (CapabilityFlag::ExecSubprocess as u64)) != 0;

        if is_high_risk_sink && header.taint_bitmask > 0 {
            for (key, val) in parameters.iter() {
                // Check for shell expansion or path traversal vectors in tainted data
                if val.contains("..") || val.contains(';') || val.contains('|') || val.contains('$') {
                    return Err(VerificationError::IllegalTaintFlow {
                        param: key.clone(),
                        sink: tool_name.to_string(),
                    });
                }
            }
        }

        Ok(())
    }
}
```

